// Model comparison stage (compare.html). Two versions of the same object, generated by different Tripo routes, stand
// exactly on top of each other; a draggable divider shows the left model left of it and the right model right of it.
// Two scenes (each with its own lights and shadow map) share one camera and are drawn as two scissored passes.
// Models are shown raw, as generated: no decimation, no texture compression.
// URL: compare.html?s=radio&l=api&r=studio-h31   (?webgl forces the WebGL2 backend)
import * as THREE from 'three/webgpu';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

const BASE = '/generated/compare/';
const q = new URLSearchParams(location.search);
const $ = (id) => document.getElementById(id);
const msg = (t, ms = 4000) => { const m = $('msg'); m.textContent = t; m.style.display = t ? 'block' : 'none'; clearTimeout(msg.t); if (t && ms) msg.t = setTimeout(() => (m.style.display = 'none'), ms); };

const manifest = await fetch(BASE + 'manifest.json').then((r) => { if (!r.ok) throw new Error('manifest ' + r.status); return r.json(); })
  .catch((e) => { msg('找不到对比模型清单(' + e.message + ')。请用开发服务器打开:npm run dev', 0); throw e; });

// ---- renderer, environment, two stages -----------------------------------------------------------------------------
const canvas = $('view');
const renderer = new THREE.WebGPURenderer({ canvas, antialias: true, alpha: true, forceWebGL: q.has('webgl') });
await renderer.init();
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight, false);
renderer.toneMapping = THREE.NeutralToneMapping; // neutral: keeps each model's texture colours as generated
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFShadowMap;
renderer.autoClear = false; // one clear per frame, then two scissored passes
renderer.setClearColor(0x000000, 0); // transparent: the studio backdrop is the page's CSS gradient
const maxAniso = renderer.getMaxAnisotropy ? renderer.getMaxAnisotropy() : 8;

const env = new THREE.PMREMGenerator(renderer).fromScene(new RoomEnvironment(), 0.04).texture;
const floorMat = new THREE.ShadowNodeMaterial({ color: 0x000000, opacity: 0.55 }); // only the cast shadow, on the backdrop

function makeStage() {
  const scene = new THREE.Scene();
  scene.environment = env; scene.environmentIntensity = 0.85;
  const key = new THREE.DirectionalLight(0xfff3e6, 2.0);
  key.position.set(-1.2, 3.6, 1.6); key.castShadow = true; // high and front-left: the shadow falls under and behind, visible from both default views
  key.shadow.mapSize.set(2048, 2048); key.shadow.bias = -0.0003; key.shadow.normalBias = 0.012; key.shadow.radius = 8;
  Object.assign(key.shadow.camera, { left: -1.1, right: 1.1, top: 1.1, bottom: -1.1, near: 0.5, far: 8 });
  const rim = new THREE.DirectionalLight(0xdde6ff, 0.7); rim.position.set(-2.4, 1.8, -2.6);
  const top = new THREE.DirectionalLight(0xffffff, 0.35); top.position.set(0.15, 5, 0.25); top.castShadow = true; // contact shadow right under the model
  top.shadow.mapSize.set(1024, 1024); top.shadow.bias = -0.0003; top.shadow.normalBias = 0.012; top.shadow.radius = 12;
  Object.assign(top.shadow.camera, { left: -1, right: 1, top: 1, bottom: -1, near: 3, far: 6.5 });
  const floor = new THREE.Mesh(new THREE.CircleGeometry(2.6, 96), floorMat);
  floor.rotation.x = -Math.PI / 2; floor.receiveShadow = true;
  const slot = new THREE.Group();
  scene.add(key, key.target, rim, top, top.target, floor, slot);
  return { scene, slot };
}
const L = makeStage(), R = makeStage();

const camera = new THREE.PerspectiveCamera(30, innerWidth / innerHeight, 0.01, 50);
const controls = new OrbitControls(camera, canvas);
controls.enableDamping = true; controls.dampingFactor = 0.08; controls.autoRotateSpeed = 0.9;
controls.minDistance = 0.15; controls.maxDistance = 8;
let dirty = 3;
controls.addEventListener('change', () => (dirty = 3));

// ---- models: loaded once, normalised (front to +Z, longest side 1 m, standing on y = 0, centred) ------------------
const loader = new GLTFLoader();
const cache = new Map(); // "subject/id" -> Promise<Group>, least recently used last
const CACHE_MAX = 4;
function prepare(root, m) {
  root.rotation.y = THREE.MathUtils.degToRad(m.yaw || 0);
  const wrap = new THREE.Group(); wrap.add(root); wrap.updateMatrixWorld(true);
  let box = new THREE.Box3().setFromObject(wrap, true); const size = box.getSize(new THREE.Vector3());
  wrap.scale.setScalar(1 / Math.max(size.x, size.y, size.z)); wrap.updateMatrixWorld(true);
  box = new THREE.Box3().setFromObject(wrap, true); const c = box.getCenter(new THREE.Vector3());
  wrap.position.set(-c.x, -box.min.y, -c.z);
  const out = new THREE.Group(); out.add(wrap); out.updateMatrixWorld(true);
  let tris = 0;
  out.traverse((o) => {
    if (!o.isMesh) return;
    o.castShadow = o.receiveShadow = true;
    tris += (o.geometry.index ? o.geometry.index.count : o.geometry.attributes.position.count) / 3;
    for (const mat of [].concat(o.material)) for (const k of ['map', 'normalMap', 'roughnessMap', 'metalnessMap', 'aoMap', 'emissiveMap']) if (mat[k]) mat[k].anisotropy = maxAniso;
  });
  out.userData = { tris, height: new THREE.Box3().setFromObject(out).getSize(new THREE.Vector3()).y };
  return out;
}
function dispose(obj) {
  obj.traverse((o) => {
    if (!o.isMesh) return; o.geometry.dispose();
    for (const mat of [].concat(o.material)) { for (const v of Object.values(mat)) if (v && v.isTexture) v.dispose(); mat.dispose(); }
  });
}
function load(subject, m, bar) {
  const key = subject + '/' + m.id;
  if (!cache.has(key)) {
    cache.set(key, new Promise((res, rej) => loader.load(BASE + encodeURI(m.file), (g) => res(prepare(g.scene, m)),
      (e) => { if (e.total) bar(e.loaded / e.total); }, rej)));
  }
  const p = cache.get(key); cache.delete(key); cache.set(key, p); // most recently used last
  for (const [k, v] of cache) { // keep memory bounded: drop the least recently used models not on screen
    if (cache.size <= CACHE_MAX) break;
    if (k === key || k === shown.L || k === shown.R) continue;
    cache.delete(k); v.then(dispose, () => {});
  }
  return p;
}

// ---- state + UI --------------------------------------------------------------------------------------------------
const subjects = Object.keys(manifest);
const state = { s: subjects.includes(q.get('s')) ? q.get('s') : subjects[0], l: q.get('l'), r: q.get('r'), split: 0.5, wire: false };
const shown = { L: null, R: null };
const fmt = (n) => n >= 1e6 ? (n / 1e6).toFixed(2) + ' 百万' : n >= 1e4 ? (n / 1e4).toFixed(1) + ' 万' : String(Math.round(n));

function statsHTML(m, tris) {
  const rows = [['设置', m.settings], ['三角面', `<b>${fmt(tris ?? m.tris)}</b>`], m.meshes > 1 ? ['部件', `${m.meshes} 个`] : null,
    ['贴图', m.textures > 3 ? `${m.maps} 等 ${m.textures} 张` : m.maps], ['文件', `${m.mb} MB`], ['花费', m.cost], ['用时', m.time]].filter(Boolean);
  return rows.map(([k, v]) => `<div><span>${k}</span><span>${v}</span></div>`).join('');
}
function fillSelect(sel, models, value) {
  sel.innerHTML = models.map((m) => `<option value="${m.id}">${m.label}</option>`).join('');
  sel.value = value;
}
function setSplit(v) {
  state.split = Math.min(1, Math.max(0, v));
  $('divider').style.left = state.split * 100 + '%'; dirty = 3;
}
function frameCamera() {
  const S = manifest[state.s], h = Math.max(shown.hL || 0.6, shown.hR || 0.6);
  const target = new THREE.Vector3(0, h * 0.48, 0), dir = new THREE.Vector3(...S.view).normalize();
  const r = 0.5 + h * 0.2, dist = r / Math.sin(THREE.MathUtils.degToRad(camera.fov / 2)) * (innerWidth < innerHeight ? 1.5 : 1.0);
  controls.target.copy(target); camera.position.copy(target).addScaledVector(dir, dist); camera.updateProjectionMatrix(); controls.update(); dirty = 3;
}
function syncURL() {
  const u = new URL(location.href); u.searchParams.set('s', state.s); u.searchParams.set('l', state.l); u.searchParams.set('r', state.r);
  history.replaceState(null, '', u);
}
async function show(side, keepCamera) {
  const S = manifest[state.s], id = side === 'L' ? state.l : state.r, m = S.models.find((x) => x.id === id) || S.models[0];
  const stage = side === 'L' ? L : R, stats = $('stats' + side), bar = $('load' + side);
  stats.innerHTML = statsHTML(m); bar.classList.add('on'); bar.innerHTML = '<i></i>';
  const key = state.s + '/' + m.id; shown[side] = key;
  try {
    const obj = await load(state.s, m, (f) => (bar.firstChild.style.width = Math.round(f * 100) + '%'));
    if (shown[side] !== key) return; // the user picked something else meanwhile
    stage.slot.clear(); const inst = obj.parent ? obj.clone() : obj;
    inst.traverse((o) => { if (o.isMesh && o.material === wireMat) o.material = o.userData.mat; }); // back to the model's own materials first
    stage.slot.add(inst);
    applyWire();
    stats.innerHTML = statsHTML(m, obj.userData.tris); shown['h' + side] = obj.userData.height;
    if (!keepCamera) frameCamera();
  } catch (e) {
    stats.innerHTML = statsHTML(m) + `<div><span>错误</span><span>加载失败:${e.message || e}</span></div>`;
  } finally { bar.classList.remove('on'); dirty = 3; }
}
// wireframe: swap in one shared line material (toggling .wireframe on the loaded glTF materials does not reach the
// node materials the WebGPU renderer derived from them); the originals are kept on the mesh and put back
const wireMat = new THREE.MeshBasicNodeMaterial({ color: 0xd9d5cc, wireframe: true });
function applyWire() {
  for (const st of [L, R]) st.slot.traverse((o) => {
    if (!o.isMesh) return;
    if (state.wire && o.material !== wireMat) { o.userData.mat = o.material; o.material = wireMat; }
    else if (!state.wire && o.material === wireMat) o.material = o.userData.mat;
  });
  dirty = 3;
}
async function setSubject(s) {
  state.s = s; const S = manifest[s], ids = S.models.map((m) => m.id);
  if (!ids.includes(state.l)) state.l = ids[0];
  if (!ids.includes(state.r) || state.r === state.l) state.r = ids.find((i) => i.startsWith('studio-h31')) || ids[1] || ids[0];
  fillSelect($('selL'), S.models, state.l); fillSelect($('selR'), S.models, state.r);
  $('refImg').src = BASE + S.ref;
  for (const b of $('subjects').children) b.classList.toggle('on', b.dataset.s === s);
  shown.hL = shown.hR = 0; syncURL();
  await Promise.all([show('L'), show('R', true)]);
  frameCamera();
}
$('subjects').innerHTML = subjects.map((s) => `<button data-s="${s}">${manifest[s].name}</button>`).join('');
$('subjects').addEventListener('click', (e) => { const s = e.target.dataset?.s; if (s && s !== state.s) setSubject(s); });
$('selL').addEventListener('change', (e) => { state.l = e.target.value; syncURL(); show('L', true); });
$('selR').addEventListener('change', (e) => { state.r = e.target.value; syncURL(); show('R', true); });
$('bRotate').addEventListener('click', (e) => { controls.autoRotate = !controls.autoRotate; e.target.classList.toggle('on', controls.autoRotate); });
$('bWire').addEventListener('click', (e) => { state.wire = !state.wire; e.target.classList.toggle('on', state.wire); applyWire(); });
$('bReset').addEventListener('click', () => { setSplit(0.5); frameCamera(); });

// divider: drag the knob or anywhere along the line; double-click returns it to the middle; arrow keys nudge it
{
  const div = $('divider'), grab = document.createElement('div'); grab.className = 'grab'; div.prepend(grab);
  let drag = false;
  const down = (e) => { drag = true; e.currentTarget.setPointerCapture(e.pointerId); e.preventDefault(); };
  const move = (e) => { if (drag) setSplit(e.clientX / innerWidth); };
  const up = () => (drag = false);
  for (const el of [grab, div.querySelector('.knob')]) {
    el.addEventListener('pointerdown', down); el.addEventListener('pointermove', move);
    el.addEventListener('pointerup', up); el.addEventListener('pointercancel', up);
    el.addEventListener('dblclick', () => setSplit(0.5));
  }
  div.addEventListener('wheel', (e) => { e.preventDefault(); canvas.dispatchEvent(new WheelEvent('wheel', e)); }, { passive: false }); // zoom works over the divider too
  addEventListener('keydown', (e) => {
    if (e.target.tagName === 'SELECT') return;
    if (e.key === 'ArrowLeft') setSplit(state.split - 0.02); else if (e.key === 'ArrowRight') setSplit(state.split + 0.02);
  });
}
addEventListener('resize', () => { renderer.setSize(innerWidth, innerHeight, false); camera.aspect = innerWidth / innerHeight; camera.updateProjectionMatrix(); dirty = 3; });

// ---- render: one clear, left scene left of the divider, right scene right of it -----------------------------------
renderer.setAnimationLoop(() => {
  const moved = controls.update();
  if (!moved && dirty <= 0) return;
  dirty--;
  const W = innerWidth, H = innerHeight, x = Math.round(W * state.split);
  renderer.setScissorTest(false); renderer.clear();
  renderer.setScissorTest(true);
  if (x > 0) { renderer.setScissor(0, 0, x, H); renderer.render(L.scene, camera); }
  if (x < W) { renderer.setScissor(x, 0, W - x, H); renderer.render(R.scene, camera); }
});
window.__compare = { state, shown, renderer, camera, controls, setSplit, setSubject, ready: () => !!(shown.hL && shown.hR) };
setSplit(0.5);
await setSubject(state.s);
